WITH ValidOrders AS (SELECT *, ADD_MONTHS(order_date, 12) AS order_date_plus_months FROM orders WHERE discount BETWEEN 0.17 AND 0.2 AND (shipping_fee >= 15 OR shipping_fee < 25)), summary AS (SELECT status, DATE_FORMAT(order_date_plus_months, 'yyyy-MM') AS order_plus_months_month, MIN(shipping_fee) AS min_shipping_fee FROM ValidOrders GROUP BY status, DATE_FORMAT(order_date_plus_months, 'yyyy-MM')) SELECT status, order_plus_months_month, min_shipping_fee FROM summary ORDER BY status, order_plus_months_month LIMIT 5
